 bool detector=false;LslHost touches=host;LslInstance* current=nullptr;touches.chat=[&](const LslChat& x){detector=current->current_event()->detectors.at(0).key==context().owner;messages.push_back(x.text);};LslInstance t(compile_lsl("default{touch_start(integer n){llSay(n-1,(string)(n+2));}}").program,context(),touches);current=&t;t.run(100);test(t.post_event({"touch_start",{std::int32_t(4)},{{context().owner}}}),"typed touch post");t.run(100);test(detector&&messages.back()=="6","parameter and actual detector retained");
