 auto queue_program=compile_lsl("default{touch_start(integer n){llOwnerSay((string)n);}}");LslInstance q(queue_program.program,context(),host);q.run(100);for(int n=0;n<64;n++)test(q.post_event({"touch_start",{std::int32_t(n)}, {}}),"per-event queue admission");test(!q.post_event({"touch_start",{std::int32_t(65)}, {}}),"queue cap64");test(q.post_event({"state_entry",{}, {}}),"independent event count");test(q.run(1).status==LslRunStatus::BudgetExhausted&&messages.back()=="0","priority empty state_entry");q.reset();test(q.queued_events()==1&&q.run(100).status==LslRunStatus::Idle,"reset clears pending events");
