 test(controlled.running()&&controlled.run(1).status==LslRunStatus::BudgetExhausted&&control_messages==std::vector<std::string>{"one"},"running initial event budget");test(controlled.post_event({"touch_start",{std::int32_t(1)}, {}}),"pending event before stop");controlled.running(false);test(!controlled.running()&&controlled.queued_events()==0&&controlled.run(100).status==LslRunStatus::Idle&&control_messages.size()==1,"stop clears pending without executing active continuation");test(controlled.current_event()&&controlled.current_event()->name=="state_entry","stop preserves active event context");test(controlled.post_event({"touch_start",{std::int32_t(1)}, {}})&&controlled.queued_events()==0&&!controlled.post_event({"missing",{}, {}}),"stopped known events ignored; unknown events rejected");controlled.running(true);test(controlled.run(100).status==LslRunStatus::Idle&&control_messages==std::vector<std::string>{"one","two"},"start resumes active PC without replay or stopped event");controlled.running(false);controlled.reset();test(!controlled.running()&&controlled.queued_events()==1&&controlled.run(100).status==LslRunStatus::Idle&&control_messages.size()==2,"reset stopped script preserves false and queues one state entry");controlled.running(true);controlled.run(100);test(control_messages==std::vector<std::string>{"one","two","one","two"},"start after stopped reset runs fresh default entry");
