 std::int64_t sleep_clock=0;std::vector<std::string> sleep_messages;LslHost sleep_host;sleep_host.clock_ticks=[&]{return sleep_clock;};sleep_host.chat=[&](const LslChat& chat){sleep_messages.push_back(chat.text);};std::string sleep_source="default{state_entry(){";for(int n=0;n<12;++n)sleep_source+="llSay(0,\"sleep\");";sleep_source+="}}";LslInstance sleeping(compile_lsl(sleep_source).program,context(),sleep_host);test(sleeping.run(100).status==LslRunStatus::Sleeping&&sleep_messages.size()>0&&sleep_messages.size()<12,"real API sleep suspends active event");auto sleeping_count=sleep_messages.size();sleeping.running(false);sleeping.run(100);sleeping.running(true);test(sleeping.run(100).status==LslRunStatus::Sleeping&&sleep_messages.size()==sleeping_count,"stop and start preserve actual sleep deadline");sleep_clock+=20000000;sleeping.run(100);test(sleep_messages.size()==12,"wake resumes remaining instructions without replay");test(fault.running(),"retained execution-faulted instance still reports running");
